#!/bin/bash
# Run from store/ on the pre-edit tree (HEAD 54a3fcc). Output must equal b-round-283/claims-284-output.txt.
echo "K1 $(git rev-parse --short=7 HEAD 2>/dev/null || echo '(archive)')"
echo "K2 $(grep -n 'const PEAK_SHAPE_MAX_COLUMNS = 4096;' app/components/arrangement/ArrangementClip.tsx)"
echo "K3 $(grep -n 'const peakColumns = Math.round(Math.min(width, PEAK_SHAPE_MAX_COLUMNS));' app/components/arrangement/ArrangementClip.tsx)"
echo "K4 $(grep -n '^export function buildPeakShape' app/components/arrangement/ArrangementClip.tsx)"
echo "K5 $(grep -n '\[peaks, clip.sourceOffset, clip.duration, columns, scale\]' app/components/arrangement/ArrangementClip.tsx)"
echo "K6 $(grep -n 'const width = clip.duration \* pxPerSecond;' app/components/arrangement/ArrangementClip.tsx)"
echo "K7 $(grep -n 'const linePoints = \[' app/components/arrangement/ArrangementClipEnvelope.tsx) | $(grep -n 'viewBox={`0 0 ${lineWidth} 1`}' app/components/arrangement/ArrangementClipEnvelope.tsx) | $(grep -c 'points={linePoints}' app/components/arrangement/ArrangementClipEnvelope.tsx)"
echo "K8 $(grep -n 'const points = visibleClipEnvelopePoints(clip);' app/components/arrangement/ArrangementClipEnvelope.tsx)"
echo "K9 $(grep -n '^export const PEAK_BUCKETS_PER_SECOND = 100;' app/lib/arrangement/peaks.ts)"
echo "K10 SWEEP PEAK_SHAPE_MAX_COLUMNS app/** perf/**: $(grep -rn 'PEAK_SHAPE_MAX_COLUMNS' app perf | wc -l) | $(grep -rln 'PEAK_SHAPE_MAX_COLUMNS' app perf | tr '\n' ' ')"
echo "K11 SWEEP envelope points/viewBox readers app/** perf/**: $(grep -rnE "getAttribute\('points'\)|getAttribute\('viewBox'\)" app perf | wc -l) | $(grep -rlE "getAttribute\('points'\)|getAttribute\('viewBox'\)" app perf | sort | tr '\n' ' ')"
echo "K12 SWEEP arrangement-clip-waveform app/** perf/**: $(grep -rln 'arrangement-clip-waveform' app perf | sort | tr '\n' ' ')"
echo "K13 SWEEP arrangement-clip-envelope-line app/** perf/**: $(grep -rln 'arrangement-clip-envelope-line' app perf | sort | tr '\n' ' ')"
echo "K14 SWEEP ArrangementPeakPath/buildPeakShape importers: $(grep -rlnE 'ArrangementPeakPath|buildPeakShape' app perf | sort | tr '\n' ' ')"
echo "K15 $(grep -n 'rulerTickMarks(seconds, pxPerSecond).map' app/components/arrangement/ArrangementRuler.tsx) | $(grep -n 'export function rulerTickMarks' app/lib/arrangement/view.ts)"
echo "K16 $(ls docs/implementation/2026/quarter-IV/ | sort | tail -1)"
echo "K17 In Progress (stage: $(grep -rn 'In Progress (stage' docs/implementation | wc -l)"
echo "K18 git status: $(git status --short 2>/dev/null | wc -l)"
echo "K19 zoom rows in perf/budgets.interactions.json: $(grep -c '"id": "interact.zoom\.' perf/budgets.interactions.json)"
echo "K20 covering files present: $(for f in waveform-outline-path.test.tsx clip-gain-waveform.test.tsx waveform-zoom.test.tsx clip-gain-pointer-preview.test.tsx content-colour-ui.test.tsx clip-envelope-ui.test.tsx strings.test.ts affordance-colour-ui.test.tsx studio-theme-obsidian.test.tsx; do test -f app/lib/arrangement/__tests__/$f && echo -n 1; done)"
